package main

import (
    "bytes"
    "encoding/json"
    "math"
    "strconv"
    "strings"
    "time"
)

type Pair struct { Key string; Value any }
type Object struct { Pairs []Pair }
func newObject() *Object { return &Object{} }
func (o *Object) Add(k string, v any) { o.Pairs = append(o.Pairs, Pair{k,v}) }
func (o *Object) Index(k string) int { for i,p := range o.Pairs {if p.Key==k {return i}}; return -1 }
func (o *Object) Get(k string) any { if i:=o.Index(k); i>=0 {return o.Pairs[i].Value}; return nil }
func (o *Object) Set(k string, v any) {if i:=o.Index(k); i>=0 {o.Pairs[i].Value=v} else {o.Add(k,v)}}
type Date struct { Time time.Time; Kind string }
func (d Date) ISO() string { return d.Time.Format(time.RFC3339Nano) }
func (d Date) TOML() string { switch d.Kind { case "date": return d.Time.Format("2006-01-02"); case "time": return d.Time.Format("15:04:05.999999999"); case "local": return d.Time.Format("2006-01-02T15:04:05.999999999") }; return d.ISO() }

type Options struct { From, To byte; Indent, Escape, Keys, NoInf bool }
func specialString(s string) any { switch s {case "Infinity": return math.Inf(1); case "-Infinity": return math.Inf(-1); case "NaN": return math.NaN()}; return s }
func transform(v any, f func(any)any) any {
    switch v:=v.(type) {
    case *Object:
        o:=newObject();for _,p:=range v.Pairs {o.Add(p.Key,transform(p.Value,f))};return o
    case []any:
        a:=make([]any,len(v));for i,x:=range v {a[i]=transform(x,f)};return a
    default:return f(v)
    }
}
func jsonQuote(s string, escape bool) string {var b bytes.Buffer;e:=json.NewEncoder(&b);e.SetEscapeHTML(escape);_ = e.Encode(s);return strings.TrimSuffix(b.String(),"\n")}
func jsonText(v any, escape, noinf bool) string {
    switch x:=v.(type) {
    case nil:return "null"
    case *Object:
        a:=[]string{};for _,p:=range x.Pairs {a=append(a,jsonQuote(p.Key,escape)+":"+jsonText(p.Value,escape,noinf))};return "{"+strings.Join(a,",")+"}"
    case []any:
        a:=[]string{};for _,v:=range x {a=append(a,jsonText(v,escape,noinf))};return "["+strings.Join(a,",")+"]"
    case string:return jsonQuote(x,escape)
    case Date:return jsonQuote(x.ISO(),escape)
    case float64:
        if math.IsInf(x,0) {if noinf {if math.IsInf(x,-1) {return "-1.7976931348623157e+308"};return "1.7976931348623157e+308"};if math.IsInf(x,-1){return `"-Infinity"`};return `"Infinity"`}
        if math.IsNaN(x) {if noinf{return "null"};return `"NaN"`}
        b,_:=json.Marshal(x);return string(b)
    default:b,_:=json.Marshal(x);return string(b)
    }
}
func keyText(v any) string {if s,ok:=v.(string);ok {return s};return jsonText(v,false,false)}

func parseJSON(s string) (any,error) {
    // RawMessage validates JSON without coercing large numbers to float64.
    var raw json.RawMessage
    if err:=json.Unmarshal([]byte(s),&raw);err!=nil{return nil,err}
    // The numeric resolver is also used for YAML scalars, preserving integral values.
    d:=json.NewDecoder(strings.NewReader(s));d.UseNumber()
    var read func()(any,error)
    read=func()(any,error) {
        t,err:=d.Token();if err!=nil{return nil,err}
        switch x:=t.(type) {
        case json.Delim:
            if x=='{' {o:=newObject();for d.More() {k,e:=d.Token();if e!=nil{return nil,e};v,e:=read();if e!=nil{return nil,e};o.Add(k.(string),v)};_,err=d.Token();return o,err}
            if x=='[' {a:=[]any{};for d.More(){v,e:=read();if e!=nil{return nil,e};a=append(a,v)};_,err=d.Token();return a,err}
        case json.Number:return resolveScalar(string(x)),nil
        default:return x,nil
        };return nil,nil
    }
    // YAML-style Unicode escapes do not allow UTF-16 surrogate code points.
    inString,slash:=false,false
    for i:=0;i<len(s);i++ {c:=s[i];if !inString {if c=='"'{inString=true};continue};if slash {slash=false;if c=='u' && i+4<len(s) {n,e:=strconv.ParseUint(s[i+1:i+5],16,16);if e==nil && n>=0xd800 && n<=0xdfff {return nil,fmtError("yaml: found invalid Unicode character escape code")}};continue};if c=='\\' {slash=true};if c=='"'{inString=false}}
    return read()
}
EOF
cat > main.go <<'EOF'
package main

import (
    "bytes"
    "encoding/json"
    "errors"
    "fmt"
    "io"
    "os"
    "strings"
)
func fmtError(s string) error {return errors.New(s)}
func help() string { return `Usage: `+os.Args[0]+` [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version

` }
func flags(args []string) (Options,bool,error) {
    o:=Options{From:'y',To:'j'};seq:=[]byte{};invalid:=[]string{};h,v:=false,false
    for _,s:=range args {for _,c:=range s {switch c {
    case '-':
    case 'y','t','j','c':seq=append(seq,byte(c))
    case 'r':seq=append(seq,'j','y')
    case 'n':o.NoInf=true
    case 'e':o.Escape=true
    case 'i':o.Indent=true
    case 'k':o.Keys=true
    case 'h':h=true
    case 'v':v=true
    default:invalid=append(invalid,string(c))
    }}}
    if len(invalid)>0 {return o,false,fmtError("invalid flags specified: "+strings.Join(invalid," "))}
    if len(seq)==1{o.From=seq[0]};if len(seq)>1{o.From=seq[len(seq)-2];o.To=seq[len(seq)-1]}
    if o.Keys && o.To!='y' {return o,false,fmtError("flag -k only valid for YAML output")}
    if o.Escape && o.To!='j' {return o,false,fmtError("flag -e only valid for JSON output")}
    if o.Indent && o.To!='j' && o.To!='t' {return o,false,fmtError("flag -i only valid for JSON or TOML output")}
    if h {fmt.Print(help());return o,true,nil};if v {fmt.Println("v0.0.0");return o,true,nil}
    return o,false,nil
}
func main() { os.Exit(run()) }
func run() int {
    o,done,err:=flags(os.Args[1:]);if err!=nil {fmt.Fprint(os.Stderr,help()+"Error: "+err.Error()+"\n");return 1};if done{return 0}
    data,err:=io.ReadAll(os.Stdin);if err!=nil {fmt.Fprintln(os.Stderr,err);return 1};s:=string(data)
    var value any
    switch o.From {case 'j':value,err=parseJSON(s);case 'y':value,err=parseYAML(s);case 't':value,err=parseTOML(s);case 'c':value,err=parseHCL(s)}
    names:=map[byte]string{'j':"JSON",'y':"YAML",'t':"TOML",'c':"HCL"}
    if err!=nil {if err==io.EOF{return 0};fmt.Fprintf(os.Stderr,"Error parsing %s: %s\n",names[o.From],err);return 1}
    if !o.NoInf && (o.From=='j'||o.From=='c') && (o.To=='y'||o.To=='t') {value=transform(value,func(v any)any {if s,ok:=v.(string);ok{return specialString(s)};return v})}
    var output string
    switch o.To {
    case 'j':output=jsonText(value,o.Escape,o.NoInf);if o.Indent {var b bytes.Buffer;_ = json.Indent(&b,[]byte(output),"","  ");output=b.String()};output+="\n"
    case 'y':output,err=writeYAML(value,o)
    case 't':output,err=writeTOML(value,o)
    case 'c':output,err=writeHCL(value,o)
    }
    if err!=nil {fmt.Fprintf(os.Stderr,"Error writing %s: %s\n",names[o.To],err);return 1}
    fmt.Print(output);return 0
}
EOF"}

