package main

import (
	"bytes"
	"encoding/json"
	"io"
	"strings"
	"testing"
)

// The golden cases cover the public conversions, including their ordering and
// formatting conventions. They do not require any external programs or data.
func convertForTest(input string, options Options) (string, error) {
	var value any
	var err error
	switch options.From {
	case 'y':
		value, err = parseYAML(input, options.NoInf)
	case 'j':
		value, err = parseJSON(input)
	case 't':
		value, err = parseTOML(input)
	case 'c':
		value, err = parseHCL(input)
	}
	if err == io.EOF {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	if !options.NoInf && (options.From == 'j' || options.From == 'c') && (options.To == 'y' || options.To == 't') {
		value = transform(value, func(value any) any {
			if s, ok := value.(string); ok {
				return specialString(s)
			}
			return value
		})
	}
	switch options.To {
	case 'j':
		out := jsonText(value, options.Escape, options.NoInf)
		if options.Indent {
			var b bytes.Buffer
			if err := json.Indent(&b, []byte(out), "", "  "); err != nil {
				return "", err
			}
			out = b.String()
		}
		return out + "\n", nil
	case 'y':
		return writeYAML(value, options)
	case 't':
		return writeTOML(value, options)
	case 'c':
		return writeHCL(value, options)
	}
	panic("unknown test format")
}

