		{"HTML escaping on", "-jje", `{"x":"<a>&"}`, "{\"x\":\"\\u003ca\\u003e\\u0026\"}\n"},
		{"YAML string conventions", "-jy", `{"yes":"true","x":[1,null],"s":"a\nb\n"}`, "\"yes\": \"true\"\nx:\n  - 1\n  - null\ns: |\n  a\n  b\n"},
