cat > converter_test.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"io"
	"strings"
	"testing"
)

// The golden cases cover the public conversions, including their ordering and
// formatting conventions. They do not require any external programs or data.
func convertForTest(input string, options Options) (string, error) {
	var value any
	var err error
	switch options.From {
	case 'y':
		value, err = parseYAML(input, options.NoInf)
	case 'j':
		value, err = parseJSON(input)
	case 't':
		value, err = parseTOML(input)
	case 'c':
		value, err = parseHCL(input)
	}
	if err == io.EOF {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	if !options.NoInf && (options.From == 'j' || options.From == 'c') && (options.To == 'y' || options.To == 't') {
		value = transform(value, func(value any) any {
			if s, ok := value.(string); ok {
				return specialString(s)
			}
			return value
		})
	}
	switch options.To {
	case 'j':
		out := jsonText(value, options.Escape, options.NoInf)
		if options.Indent {
			var b bytes.Buffer
			if err := json.Indent(&b, []byte(out), "", "  "); err != nil {
				return "", err
			}
			out = b.String()
		}
		return out + "\n", nil
	case 'y':
		return writeYAML(value, options)
	case 't':
		return writeTOML(value, options)
	case 'c':
		return writeHCL(value, options)
	}
	panic("unknown test format")
}

func TestConversions(t *testing.T) {
	tests := []struct {
		name, flags, input, want string
	}{
		{"map order and duplicates", "-yj", "z: 1\na: 2\nz: 3\n", "{\"z\":1,\"a\":2,\"z\":3}\n"},
		{"first YAML document", "-y", "a: 1\n---\nb: 2\n", "{\"a\":1}\n"},
		{"empty YAML stream", "-y", "# comment\n", ""},
		{"numeric types", "-yy", "a: 01\nb: 0129\nc: 1e3\nd: yes\n", "a: 1\nb: 129.0\nc: 1000.0\nd: \"yes\"\n"},
		{"anchors and merge order", "-y", "a: &a {x: 1, y: 2}\nb: {<<: *a, x: 4}\n", "{\"a\":{\"x\":1,\"y\":2},\"b\":{\"x\":1,\"y\":2,\"x\":4}}\n"},
		{"nested sequences", "-y", "- - a: 1\n    b: 2\n  - c: 3\n", "[[{\"a\":1,\"b\":2},{\"c\":3}]]\n"},
		{"YAML block text", "-y", "a: >\n  hello\n  world\n\n  next\nb: |-\n  xx\n  yy\n", "{\"a\":\"hello world\\nnext\\n\",\"b\":\"xx\\nyy\"}\n"},
		{"JSON number normalization", "-jj", `{"a":9223372036854775807,"b":1.0,"c":1e3}`, "{\"a\":9223372036854775807,\"b\":1,\"c\":1000}\n"},
		{"JSON indentation", "-jji", `{"b":[1,true],"a":{}}`, "{\n  \"b\": [\n    1,\n    true\n  ],\n  \"a\": {}\n}\n"},
		{"HTML escaping off", "-jj", `{"x":"<a>&"}`, "{\"x\":\"<a>&\"}\n"},
		{"HTML escaping on", "-jje", `{"x":"<a>&"}`, "{\"x\":\"\\u003ca\\u003e\\u0026\"}\n"},
		{"YAML string conventions", "-jy", `{"yes":"true","x":[1,null],"s":"a\nb\n"}`, "\"yes\": \"true\"\nx:\n  - 1\n  - null\ns: |\n  a\n  b\n"},
		{"parsed YAML keys", "-jyk", `{"[1,2]":"value","true":1}`, "? - 1\n  - 2\n: value\ntrue: 1\n"},
		{"special floats to strings", "-yj", "a: .inf\nb: -.inf\nc: .nan\n", "{\"a\":\"Infinity\",\"b\":\"-Infinity\",\"c\":\"NaN\"}\n"},
		{"special floats without strings", "-yjn", "a: .inf\nb: -.inf\nc: .nan\n", "{\"a\":1.7976931348623157e+308,\"b\":-1.7976931348623157e+308,\"c\":null}\n"},
		{"special float keys", "-yy", ".inf: x\n.nan: y\n", ".inf: x\n.nan: \"y\"\n"},
		{"TOML types", "-tj", "title = 'example'\n[settings]\nenabled=true\nports=[80,443]\n", "{\"title\":\"example\",\"settings\":{\"enabled\":true,\"ports\":[80,443]}}\n"},
		{"TOML table arrays", "-tj", "[[products]]\nname='a'\n[[products]]\nname='b'\n", "{\"products\":[{\"name\":\"a\"},{\"name\":\"b\"}]}\n"},
		{"TOML output grouping", "-jt", `{"a":1,"empty":{},"tables":[{"x":1},{"x":2}]}`, "a = 1\n\n[empty]\n\n[[tables]]\nx = 1\n\n[[tables]]\nx = 2\n"},
		{"indented TOML", "-jti", `{"a":{"b":{"c":1},"x":2}}`, "[a]\n  x = 2\n  [a.b]\n    c = 1\n"},
		{"TOML omits nulls", "-jt", `{"a":null,"b":[null,1,null]}`, "b = [1]\n"},
		{"TOML scalar root", "-jt", `"hello"`, `"hello"`},
		{"timestamp normalization", "-tj", "x=1979-05-27\ny=07:32:00.123\n", "{\"x\":\"1979-05-27T00:00:00Z\",\"y\":\"0000-01-01T07:32:00.123Z\"}\n"},
		{"HCL labeled blocks", "-cj", "foo \"a\" {x=1}\nfoo \"b\" {y=2}\n", "{\"foo\":[{\"a\":[{\"x\":1}],\"b\":[{\"y\":2}]}]}\n"},
		{"HCL empty and boolean lists", "-cj", "a=[]\nb=[true,false,1]\n", "{\"b\":[true,false,1]}\n"},
		{"HCL JSON list behavior", "-jc", `{"a":[true,false,1],"b":null}`, "\"a\" = [1]\n\n\"b\" = "},
		{"HCL nested labels", "-jc", `{"a":{"b":{"c":1}}}`, "\"a\" \"b\" {\n  \"c\" = 1\n}"},
		{"HCL interpolation strings", "-cj", `a="${file("foo")}"`, "{\"a\":\"${file(\\\"foo\\\")}\"}\n"},
		{"HCL heredoc", "-cj", "a=<<-EOF\n  hi\n  world\n  EOF\n", "{\"a\":\"hi\\nworld\\n\"}\n"},
		{"HCL incomplete JSON object", "-cj", "{", "{}\n"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			o, done, err := flags(strings.Fields(tc.flags))
			if err != nil || done {
				t.Fatalf("flags: %v", err)
			}
			got, err := convertForTest(tc.input, o)
			if err != nil {
				t.Fatal(err)
			}
			if got != tc.want {
				t.Fatalf("got %q\nwant %q", got, tc.want)
			}
		})
	}
}

func TestDiagnostics(t *testing.T) {
	tests := []struct{ flags, input, want string }{
		{"-jj", `{"a":}`, "invalid character '}' looking for beginning of value"},
		{"-jj", `"\ud83d\ude00"`, "yaml: found invalid Unicode character escape code"},
		{"-y", "a: [1, 2", "yaml: line 1: did not find expected ',' or ']'"},
		{"-y", "a: *bad", "yaml: unknown anchor 'bad' referenced"},
		{"-y", "a: &x [*x]", "anchor 'x' value contains itself"},
		{"-y", "a: !!int abc", "scalar decode error: yaml: cannot decode !!str `abc` as a !!int"},
		{"-y", "a: {<<: [{x: 1}]}", "map merge requires map or sequence of maps as the value"},
		{"-t", "a=01", `toml: line 1 (last key "a"): Invalid integer "01": cannot have leading zeroes`},
		{"-t", "a=1\na=2", "toml: line 2 (last key \"a\"): Key 'a' has already been defined."},
		{"-t", "a = null", `toml: line 1 (last key "a"): expected value but found "null" instead`},
		{"-c", "a=null", "At 1:3: Unknown token: 1:3 IDENT null"},
		{"-c", "x { a=1", "At 1:11: object expected closing RBRACE got: EOF"},
		{"-c", "a=[1 2]", "At 1:6: error parsing list, expected comma or list end, got: NUMBER"},
		{"-jc", `{"a":[null]}`, "unexpected token while parsing list: NULL"},
		{"-jyk", `{"null":1}`, "reflect: call of reflect.Value.Set on zero Value"},
	}
	for _, tc := range tests {
		o, _, err := flags([]string{tc.flags})
		if err != nil {
			t.Fatal(err)
		}
		_, err = convertForTest(tc.input, o)
		if err == nil || err.Error() != tc.want {
			t.Errorf("%s %q: got %v; want %s", tc.flags, tc.input, err, tc.want)
		}
	}
}

func TestFlagSelection(t *testing.T) {
	for _, tc := range []struct {
		args []string
		from, to byte
	}{
		{nil, 'y', 'j'},
		{[]string{"-r"}, 'j', 'y'},
		{[]string{"-t"}, 't', 'j'},
		{[]string{"-j", "-y", "-t"}, 'y', 't'},
		{[]string{"--", "j-y-j"}, 'y', 'j'},
	} {
		o, _, err := flags(tc.args)
		if err != nil || o.From != tc.from || o.To != tc.to {
			t.Errorf("%v: got %+v, %v", tc.args, o, err)
		}
	}
	for _, tc := range []struct{ arg, err string }{
		{"-z", "invalid flags specified: z"},
		{"-jjk", "flag -k only valid for YAML output"},
		{"-jye", "flag -e only valid for JSON output"},
		{"-jci", "flag -i only valid for JSON or TOML output"},
	} {
		_, _, err := flags([]string{tc.arg})
		if err == nil || err.Error() != tc.err {
			t.Errorf("%s: %v", tc.arg, err)
		}
	}
}
